--
-- Table structure for table `penilaian`
--

DROP TABLE IF EXISTS `penilaian`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penilaian` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `client_uuid` char(36) NOT NULL,
  `juri_id` int(11) NOT NULL,
  `karya_id` int(11) NOT NULL,
  `status` enum('DRAFT','FINAL') NOT NULL DEFAULT 'DRAFT',
  `catatan` text DEFAULT NULL,
  `skor_juri` decimal(7,4) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  `client_updated_at` bigint(20) NOT NULL DEFAULT 0,
  `finalized_at` datetime(3) DEFAULT NULL,
  `input_oleh` enum('JURI','ADMIN') NOT NULL DEFAULT 'JURI',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `penilaian_client_uuid_key` (`client_uuid`),
  UNIQUE KEY `penilaian_juri_id_karya_id_key` (`juri_id`,`karya_id`),
  KEY `penilaian_karya_id_status_idx` (`karya_id`,`status`),
  CONSTRAINT `penilaian_juri_id_fkey` FOREIGN KEY (`juri_id`) REFERENCES `juri` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `penilaian_karya_id_fkey` FOREIGN KEY (`karya_id`) REFERENCES `karya` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_skor_juri` CHECK (`skor_juri` is null or `skor_juri` >= 0 and `skor_juri` <= 100)
) ENGINE=InnoDB AUTO_INCREMENT=228 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

